package app.dawnbreaker.mobile;
import android.service.wallpaper.WallpaperService;import android.view.*;import android.webkit.*;import android.media.MediaPlayer;import android.graphics.*;import android.content.*;import android.os.*;import org.json.*;import java.io.*;
public class DawnWallpaperService extends WallpaperService{
 @Override public Engine onCreateEngine(){return new Scene();}
 class Scene extends Engine{
  final Handler handler=new Handler(Looper.getMainLooper());WebView web;MediaPlayer player;boolean visible=false,ready=false;int width=1,height=1;JSONObject variant;File folder;
  final Runnable videoControl=new Runnable(){public void run(){if(player!=null&&ready){boolean paused=WallpaperState.read(DawnWallpaperService.this).optBoolean("paused",false);try{if(visible&&!paused&&!player.isPlaying())player.start();else if((!visible||paused)&&player.isPlaying())player.pause();}catch(Exception ignored){}}handler.postDelayed(this,500);}};
  final Runnable frame=new Runnable(){public void run(){if(web!=null&&visible&&ready){if(!WallpaperState.read(DawnWallpaperService.this).optBoolean("paused",false)){Canvas canvas=null;try{canvas=getSurfaceHolder().lockCanvas();if(canvas!=null){canvas.drawColor(Color.BLACK);web.draw(canvas);}}catch(Exception ignored){}finally{if(canvas!=null)getSurfaceHolder().unlockCanvasAndPost(canvas);}}handler.postDelayed(this,67);}}};
  @Override public void onCreate(SurfaceHolder holder){super.onCreate(holder);setTouchEventsEnabled(false);try{JSONObject p=WallpaperState.read(DawnWallpaperService.this);String id=p.optString(isPreview()?"candidate":"active","");if(!isPreview()&&!p.optString("candidate").isEmpty()){id=p.optString("candidate");WallpaperState.update(DawnWallpaperService.this,new JSONObject().put("active",id).put("candidate",""));}WallpaperProjects projects=new WallpaperProjects(DawnWallpaperService.this,"");folder=projects.folder(id);variant=projects.manifest(folder).getJSONObject("variants").getJSONObject("mobile");}catch(Exception ignored){variant=null;}}
  @Override public void onSurfaceCreated(SurfaceHolder holder){super.onSurfaceCreated(holder);if(variant==null)return;String kind=variant.optString("kind");if(kind.equals("video"))startVideo(holder);else if(kind.equals("web"))startWeb();}
  void startVideo(SurfaceHolder holder){try{player=new MediaPlayer();player.setDataSource(new File(folder,variant.getString("entry")).getAbsolutePath());player.setSurface(holder.getSurface());player.setLooping(true);player.setVolume(0,0);player.setVideoScalingMode(variant.optString("fit","cover").equals("cover")?MediaPlayer.VIDEO_SCALING_MODE_SCALE_TO_FIT_WITH_CROPPING:MediaPlayer.VIDEO_SCALING_MODE_SCALE_TO_FIT);player.setOnPreparedListener(p->{ready=true;if(visible)p.start();handler.post(videoControl);});player.prepareAsync();}catch(Exception ignored){release();}}
  @SuppressWarnings("SetJavaScriptEnabled") void startWeb(){web=new WebView(DawnWallpaperService.this);web.setLayerType(View.LAYER_TYPE_SOFTWARE,null);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMediaPlaybackRequiresUserGesture(true);web.setBackgroundColor(Color.BLACK);web.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(PermissionRequest r){r.deny();}});web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){android.net.Uri uri=request.getUrl();if("wallpaper.local".equals(uri.getHost()))try{String entry=uri.getPath().substring(1);if(!WallpaperProjects.safe(entry))throw new Exception();File file=new File(folder,entry);if(!file.getCanonicalPath().startsWith(folder.getCanonicalPath()+File.separator))throw new Exception();String mime=java.net.URLConnection.guessContentTypeFromName(file.getName());if(file.getName().endsWith(".css"))mime="text/css";if(file.getName().endsWith(".js"))mime="application/javascript";return new WebResourceResponse(mime==null?"application/octet-stream":mime,"UTF-8",new FileInputStream(file));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",null,new ByteArrayInputStream(new byte[0]));}if(!"https".equals(uri.getScheme()))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));return null;}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !"https".equals(r.getUrl().getScheme());}@Override public void onPageFinished(WebView v,String u){ready=true;resize();handler.removeCallbacks(frame);handler.post(frame);}});resize();String source=variant.optString("url");if(source.isEmpty())source="https://wallpaper.local/"+variant.optString("entry");web.loadUrl(source);}
  void resize(){if(web!=null){web.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));web.layout(0,0,width,height);}}
  @Override public void onSurfaceChanged(SurfaceHolder h,int f,int w,int v){super.onSurfaceChanged(h,f,w,v);width=w;height=v;resize();}
  @Override public void onVisibilityChanged(boolean v){visible=v;boolean paused=WallpaperState.read(DawnWallpaperService.this).optBoolean("paused",false);if(player!=null&&ready){if(v&&!paused)player.start();else player.pause();}if(web!=null){if(v){web.onResume();handler.removeCallbacks(frame);handler.post(frame);}else{web.onPause();handler.removeCallbacks(frame);}}}
  @Override public void onSurfaceDestroyed(SurfaceHolder h){release();super.onSurfaceDestroyed(h);}
  void release(){ready=false;handler.removeCallbacks(frame);handler.removeCallbacks(videoControl);if(player!=null){player.release();player=null;}if(web!=null){web.destroy();web=null;}}
  @Override public void onDestroy(){release();super.onDestroy();}
 }
}
